#include <Adafruit_GFX.h>
#include <MCUFRIEND_kbv.h>
MCUFRIEND_kbv tft;
void setup() {
  uint16_t ID = tft.readID();
  tft.begin(ID);
  tft.setRotation(1);
  tft.fillScreen(0x0000); // Black
  tft.setTextColor(0xFFFF); // White
  tft.setTextSize(2);
  tft.setCursor(20, 30);
  tft.println("BUS TRACKING SYSTEM");
}
void loop() {}
